mapper.sql:
where 1=1

		and ctar_llave = #{llaveTabla}


		and ctar_estado = #{estado}


		and ctar_tarifario = #{tarifario}


		and ctar_documento = #{documento}


		and ctar_producto = #{producto}


		and ctar_productodocumento = #{productoDocumento}


		and ctar_recurso = #{recurso}


		and btar_rangoprecios = #{rangoPreciosFilter}


		and ctar_dimension2 = #{dimension2}


		and ctar_dimension3 = #{dimension3}


		and ctar_dimension4 = #{dimension4}


		and (  upper(descripcion(ctar_recurso)) like upper('%' || #{filtroParametro} || '%') or  
				upper(descripcion(ctar_dimension2)) like upper('%' || #{filtroParametro} || '%')or
				upper(descripcion(ctar_dimension3)) like upper('%' || #{filtroParametro} || '%') or
				upper(descripcion(ctar_dimension4)) like upper('%' || #{filtroParametro} || '%'))

mapper.select:
select cpdv_llave as key, cpdv_nombre as code, (select cpro_llave from producto_prop where cpro_documento = cpdv_llave) as productId, cpdv_plantilla as template, descripcion(cpdv_llave) as name from pedidoventa_pdvp where cpdv_estado = 'A' and (cpdv_nombre like upper('%' || #{filter} || '%') or cpdv_textofiltro like '%' || #{filter} || '%')
and cpdv_plantilla = #{template}
and cpdv_plantilla in (select cppd_campo from propiedad_ppdp inner join documentoplantilla_dplp on (cdpl_llave = cppd_campo) where cppd_propiedadvalor = 'PROP_144' and cppd_estado = 'A' and cdpl_estado = 'A')
